begin;
set local search_path=public,extensions;
select no_plan();
create temp table draft_fx(key text primary key,value jsonb);
insert into draft_fx select key,to_jsonb(gen_random_uuid())from unnest(array['admin','admin_session','staff','staff_session','entry','entry2','product','product2','service','vaccine','action','cancelled','expired','stale'])key;
insert into auth.users(id,email,raw_user_meta_data)select(value#>>'{}')::uuid,'draft-'||(value#>>'{}')||'@example.test','{}'from draft_fx where key in('admin','staff');
update profiles set is_active=true,full_name='Synthetic controlled draft reviewer'where id in(select(value#>>'{}')::uuid from draft_fx where key in('admin','staff'));
insert into user_roles(user_id,role)select(value#>>'{}')::uuid,'ADMIN'from draft_fx where key='admin'on conflict do nothing;
insert into user_roles(user_id,role)select(value#>>'{}')::uuid,'STAFF'from draft_fx where key='staff'on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)select(value#>>'{}')::uuid,(select(value#>>'{}')::uuid from draft_fx where key=replace(s.key,'_session','')),now(),now()from draft_fx s where key in('admin_session','staff_session');
create function pg_temp.draft_id(k text)returns uuid language sql as $$select(value#>>'{}')::uuid from draft_fx where key=k$$;
create function pg_temp.draft_claim(k text,r text default 'authenticated')returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('role',r,'sub',pg_temp.draft_id(k),'session_id',pg_temp.draft_id(k||'_session'))::text,true);end $$;
create function pg_temp.draft_packet(product text default 'product',entry text default 'entry',expected integer default null,pv integer default 1)returns jsonb language sql as $$
 select jsonb_build_object('id',pg_temp.draft_id(entry),'expected_version',expected,'definition',jsonb_build_object('product_id',pg_temp.draft_id(product),'product_version',pv,'stock_unit','mL','generic_name','Synthetic substance','brand_name',null,'schedule','II','concentration','10 mg/mL','concentration_source','Synthetic label for test only','classification_source','Synthetic source for test only','configuration_note','Draft only; no stock or registration authority'),'review_note','Synthetic draft review','attest_review',true)
$$;
create function pg_temp.draft_apply(action uuid,packet jsonb)returns jsonb language plpgsql as $$declare result jsonb;begin
 perform prepare_controlled_draft_review(pg_temp.draft_id('admin'),action,'draft_configuration',packet);
 result:=execute_controlled_draft_review(pg_temp.draft_id('admin'),action);set constraints all immediate;set constraints all deferred;return result;
end $$;
select pg_temp.draft_claim('admin');
select create_inventory_product(pg_temp.draft_id('product'),'Synthetic draft medication','medication','Synthetic manufacturer','mL',100);
select create_inventory_product(pg_temp.draft_id('product2'),'Synthetic other medication','medication','Synthetic manufacturer','mL',100);
select create_inventory_product(pg_temp.draft_id('service'),'Synthetic service','service','Synthetic manufacturer','mL',100);
select create_inventory_product(pg_temp.draft_id('vaccine'),'Synthetic vaccine','vaccine','Synthetic manufacturer','mL',100);
insert into draft_fx values('baseline',jsonb_build_object('movements',(select count(*)from inventory_movements),'invoices',(select count(*)from billing_invoices),'outbox',(select count(*)from communication_outbox),'payments',(select count(*)from payment_provider_profiles)));
select ok(relrowsecurity,'Private draft RLS: '||relname)from pg_class where relnamespace='public'::regnamespace and relname in('controlled_draft_entries','controlled_draft_reviews','controlled_draft_versions','controlled_draft_actions','controlled_draft_cancellations');
select ok(not has_table_privilege(role,relation,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),'Raw draft access denied: '||role||'/'||relation)
 from unnest(array['anon','authenticated','service_role'])role cross join unnest(array['controlled_draft_entries','controlled_draft_reviews','controlled_draft_versions','controlled_draft_actions','controlled_draft_cancellations'])relation;
select ok(not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE')and has_function_privilege('authenticated',oid,'EXECUTE'),'Guarded draft RPC: '||proname)from pg_proc where pronamespace='public'::regnamespace and proname in('prepare_controlled_draft_review','execute_controlled_draft_review','read_controlled_draft_review','cancel_controlled_draft_review','list_controlled_drafts','read_controlled_draft');
select ok(not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE'),'Private draft helper: '||proname)from pg_proc where pronamespace='public'::regnamespace and proname like 'controlled_draft_%';
select throws_ok($$select controlled_draft_validate('activate',pg_temp.draft_packet())$$,'23514',null,'Physical activation cannot be prepared as draft metadata');
select throws_ok($$select controlled_draft_validate('draft_configuration',pg_temp.draft_packet()||'{"active":true}')$$,'23514',null,'Unknown activation field rejected');
select throws_ok($$select controlled_draft_validate('draft_configuration',jsonb_set(pg_temp.draft_packet(),'{definition,schedule}','"I"'))$$,'23514',null,'Unsupported proposed schedule rejected');
select throws_ok($$select controlled_draft_validate('draft_configuration',jsonb_set(pg_temp.draft_packet(),'{definition,schedule}','2'))$$,'23514',null,'Schedule does not coerce numeric input');
select throws_ok($$select controlled_draft_validate('draft_configuration',jsonb_set(pg_temp.draft_packet(),'{definition,stock_unit}','"mg"'))$$,'PT409',null,'Draft canonical unit must match medication');
select throws_ok($$select controlled_draft_validate('draft_configuration',pg_temp.draft_packet('service'))$$,'PT409',null,'Service cannot become a controlled-medication draft');
select throws_ok($$select controlled_draft_validate('draft_configuration',pg_temp.draft_packet('vaccine'))$$,'PT409',null,'Vaccine cannot become a controlled-medication draft');
select throws_ok($$select controlled_draft_validate('draft_configuration',jsonb_set(pg_temp.draft_packet(),'{definition,classification_source}','""'))$$,'23514',null,'Classification provenance required');
select throws_ok($$select controlled_draft_validate('draft_configuration',jsonb_set(pg_temp.draft_packet(),'{definition,concentration}',to_jsonb(E'10\tmg/mL'::text)))$$,'23514',null,'Concentration is clean reviewed text, not parsed quantity');
select throws_ok($$select controlled_draft_validate('draft_configuration',pg_temp.draft_packet()-'attest_review')$$,'23514',null,'Explicit draft-only attestation required');
select throws_ok($$select prepare_controlled_draft_review(pg_temp.draft_id('admin'),'00000000-0000-0000-0000-000000000000','draft_configuration',pg_temp.draft_packet())$$,'23514',null,'Zero request UUID rejected');
select throws_ok($$select controlled_draft_validate('draft_configuration',jsonb_set(pg_temp.draft_packet(),'{definition,generic_name}',to_jsonb(chr(160)||'Synthetic substance')))$$,'23514',null,'Unicode edge whitespace matches the browser contract');
select pg_temp.draft_claim('staff');
select throws_ok($$select prepare_controlled_draft_review(pg_temp.draft_id('staff'),gen_random_uuid(),'draft_configuration',pg_temp.draft_packet())$$,'42501',null,'STAFF cannot publish classification draft');
select throws_ok($$select controlled_draft_actor(pg_temp.draft_id('admin'))$$,'42501',null,'Actor cannot be substituted');
select pg_temp.draft_claim('admin','service_role');
select throws_ok($$select list_controlled_drafts()$$,'42501',null,'Service claim cannot replace staff session');
select pg_temp.draft_claim('admin');
insert into draft_fx values('saved',pg_temp.draft_apply(pg_temp.draft_id('action'),pg_temp.draft_packet()));
select is((select state from controlled_draft_entries where id=pg_temp.draft_id('entry')),'draft','Only draft state is materialized');
select is((select count(*)from controlled_draft_versions where entry_id=pg_temp.draft_id('entry')),1::bigint,'One reviewed immutable version');
select is(execute_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('action')),(select value from draft_fx where key='saved'),'Exact execute receipt replay');
select is(read_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('action'))->'receipt',(select value from draft_fx where key='saved'),'Owned read recovers original receipt');
set local timezone='Pacific/Honolulu';
select is(read_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('action'))->'receipt',(select value from draft_fx where key='saved'),'Receipt remains byte-equivalent across caller timezone');
select is(cancel_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('action'))->'receipt',(select value from draft_fx where key='saved'),'Cancel after commit returns original saved evidence');
select throws_ok($$select prepare_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('action'),'draft_configuration',pg_temp.draft_packet()||'{"review_note":"Different"}')$$,'23505',null,'Same UUID cannot change request');
select throws_ok($$select pg_temp.draft_apply(gen_random_uuid(),pg_temp.draft_packet('product','entry2'))$$,'23505',null,'Second draft ID cannot claim same medication');
select pg_temp.draft_claim('staff');
select is(jsonb_array_length(list_controlled_drafts('Synthetic draft medication')->'items'),1,'Staff can read draft-only metadata');
select is(read_controlled_draft(pg_temp.draft_id('entry'))->'entry',(select value->'entry'from draft_fx where key='saved'),'Staff history preserves exact recorded snapshot');
select throws_ok($$select read_controlled_draft_review(pg_temp.draft_id('staff'),pg_temp.draft_id('action'))$$,'42501',null,'Staff cannot adopt reviewer recovery');
select pg_temp.draft_claim('admin');
select is(cancel_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('cancelled'))->>'cancelled','true','Cancel-before-prepare creates permanent tombstone');
select is(read_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('cancelled'))->>'state','cancelled','Missing preparation cancellation remains recoverable');
select throws_ok($$select prepare_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('cancelled'),'draft_configuration',pg_temp.draft_packet('product2','entry2'))$$,'PT409',null,'Late preparation cannot revive cancelled UUID');
select prepare_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('stale'),'draft_configuration',pg_temp.draft_packet('product','entry',1));
select save_catalog_product(pg_temp.draft_id('product'),1,'Synthetic revised medication','medication','Synthetic manufacturer','mL',100,true);
select throws_ok($$select execute_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('stale'))$$,'PT409',null,'Catalog change invalidates pending draft');
select is(execute_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('action')),(select value from draft_fx where key='saved'),'Committed replay precedes current catalog freshness');
insert into draft_fx values('revised',pg_temp.draft_apply(gen_random_uuid(),pg_temp.draft_packet('product','entry',1,2)));
select is((read_controlled_draft(pg_temp.draft_id('entry'),null,1)->>'next')::integer,2,'History pagination continues from exact oldest returned version');
select is(jsonb_array_length(read_controlled_draft(pg_temp.draft_id('entry'),2,1)->'history'),1,'Older immutable version remains readable');
select throws_ok($$update controlled_draft_entries set state='active'where id=pg_temp.draft_id('entry')$$,'23514',null,'Draft cannot be toggled into active register');
select throws_ok($$update controlled_draft_versions set definition='{}'where entry_id=pg_temp.draft_id('entry')$$,'23514',null,'Original drug classification cannot be overwritten');
select throws_ok($$delete from controlled_draft_reviews$$,'23514',null,'Prepared review evidence cannot be deleted');
select throws_ok($$truncate controlled_draft_cancellations$$,'23514',null,'Cancellation tombstones cannot be truncated');
select throws_ok($$update controlled_draft_actions set receipt='{}'$$,'23514',null,'Saved recovery receipts cannot be overwritten');
insert into controlled_draft_reviews(id,actor_id,session_id,operation,request,created_at,expires_at)values(pg_temp.draft_id('expired'),pg_temp.draft_id('admin'),pg_temp.draft_id('admin_session'),'draft_configuration',pg_temp.draft_packet('product2','entry2'),clock_timestamp()-interval '20 minutes',clock_timestamp()-interval '1 minute');
select is(read_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('expired'))->>'state','expired','Expired preparation remains visible');
select throws_ok($$select execute_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('expired'))$$,'PT409',null,'Expired review cannot publish metadata');
update auth.sessions set not_after=clock_timestamp()where id=pg_temp.draft_id('admin_session');
select throws_ok($$select read_controlled_draft_review(pg_temp.draft_id('admin'),pg_temp.draft_id('action'))$$,'42501',null,'Revoked live session cannot recover sensitive draft');
update auth.sessions set not_after=null where id=pg_temp.draft_id('admin_session');
create function pg_temp.corrupt_draft_receipt()returns trigger language plpgsql as $$begin new.receipt:='{}';return new;end $$;
create trigger test_corrupt_draft_receipt before insert on controlled_draft_actions for each row execute function pg_temp.corrupt_draft_receipt();
select throws_ok($$select pg_temp.draft_apply(gen_random_uuid(),pg_temp.draft_packet('product2','entry2'))$$,'23514',null,'Deferred receipt/source constraint rolls back a forged saved outcome');
select is((select count(*)from controlled_draft_entries where product_id=pg_temp.draft_id('product2')),0::bigint,'Failed deferred validation leaves no draft head');
drop trigger test_corrupt_draft_receipt on controlled_draft_actions;
set constraints all immediate;
select is(jsonb_build_object('movements',(select count(*)from inventory_movements),'invoices',(select count(*)from billing_invoices),'outbox',(select count(*)from communication_outbox),'payments',(select count(*)from payment_provider_profiles)),(select value from draft_fx where key='baseline'),'Draft work preserves stock, billing, payments and communication');
select *from finish();
rollback;
